import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'firebase_options.dart';

Future<void> initializeFirebase() async {
  try {
    // 이미 초기화되었는지 확인
    if (Firebase.apps.isEmpty) {
      await Firebase.initializeApp(
        options: DefaultFirebaseOptions.currentPlatform,
      );
      debugPrint('Firebase 초기화 성공');
    } else {
      debugPrint('Firebase 이미 초기화됨');
    }

    // 초기화 정보 출력
    final app = Firebase.app();
    debugPrint('App name: ${app.name}');
    debugPrint('Project ID: ${app.options.projectId}');
    debugPrint('API Key: ${app.options.apiKey.substring(0, 10)}...');
    debugPrint('Storage Bucket: ${app.options.storageBucket}');
  } on FirebaseException catch (e) {
    debugPrint('FirebaseException: ${e.code} - ${e.message}');
    rethrow;
  } catch (e) {
    debugPrint('Unknown error: $e');
    rethrow;
  }
}

// 앱 삭제 (테스트용)
Future<void> deleteFirebaseApp([String name = defaultFirebaseAppName]) async {
  try {
    await Firebase.app(name).delete();
    debugPrint('Firebase 앱 삭제됨: $name');
  } catch (e) {
    debugPrint('앱 삭제 실패: $e');
  }
}

