class FirebaseStatusWidget extends StatelessWidget {
  const FirebaseStatusWidget({super.key});

  @override
  Widget build(BuildContext context) {
    final isInitialized = Firebase.apps.isNotEmpty;

    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Icon(
                  isInitialized ? Icons.check_circle : Icons.error,
                  color: isInitialized ? Colors.green : Colors.red,
                ),
                const SizedBox(width: 8),
                Text(
                  isInitialized ? 'Firebase 연결됨' : 'Firebase 미연결',
                  style: const TextStyle(fontWeight: FontWeight.bold),
                ),
              ],
            ),
            if (isInitialized) ...[
              const Divider(),
              Text('앱: ${Firebase.app().name}'),
              Text('프로젝트: ${Firebase.app().options.projectId}'),
            ],
          ],
        ),
      ),
    );
  }
}
